package vn.edu.eaut.lab7.controller; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.*; import vn.edu.eaut.lab7.model.DiemSinhVien; import vn.edu.eaut.lab7.repository.DiemRepository; @WebServlet("/diem") public class DiemController extends HttpServlet {private final DiemRepository repo=new DiemRepository(); protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String a=req.getParameter("action");if("new".equals(a)){req.getRequestDispatcher("/views/diem/form.jsp").forward(req,resp);return;}if("edit".equals(a)){req.setAttribute("diem",repo.findById(Integer.parseInt(req.getParameter("id"))));req.getRequestDispatcher("/views/diem/form.jsp").forward(req,resp);return;}if("delete".equals(a)){repo.delete(Integer.parseInt(req.getParameter("id")));resp.sendRedirect(req.getContextPath()+"/diem");return;}req.setAttribute("dsDiem",repo.findAll());req.getRequestDispatcher("/views/diem/list.jsp").forward(req,resp);} protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{try{int id=req.getParameter("id")==null||req.getParameter("id").isBlank()?0:Integer.parseInt(req.getParameter("id"));double cc=Double.parseDouble(req.getParameter("chuyenCan")),gk=Double.parseDouble(req.getParameter("giuaKy")),ck=Double.parseDouble(req.getParameter("cuoiKy"));if(cc<0||cc>10||gk<0||gk>10||ck<0||ck>10)throw new IllegalArgumentException();DiemSinhVien d=new DiemSinhVien(id,req.getParameter("maSinhVien"),req.getParameter("hoTen"),cc,gk,ck);if(id==0)repo.add(d);else repo.update(d);resp.sendRedirect(req.getContextPath()+"/diem");}catch(Exception e){resp.sendRedirect(req.getContextPath()+"/diem?action=new&error=invalid");}}}